(()=>{'use strict';
const VERSION='20260729-historical-teams-v2';
const DATA_URL=`team-data/historical-teams.json?v=${VERSION}`;
const directory=document.getElementById('historical-teams-directory');
const profile=document.getElementById('historical-team-profile');
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char]));
const norm=value=>String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'').trim();
const fmt=value=>(Number(value)||0).toLocaleString('pt-BR');
let payload=null;
async function loadData(){
  if(payload)return payload;
  const response=await fetch(DATA_URL,{cache:'default'});
  if(!response.ok)throw new Error('Não foi possível carregar as equipes.');
  payload=await response.json();
  return payload;
}
function safeLogo(team){return team.logo||'escudo.webp'}
function tsvRows(text){return String(text||'').replace(/\r/g,'').split('\n').filter(Boolean).map(row=>row.split('\t'))}
function splitPeople(value){return String(value||'').split(/[,;|\n]+/).map(item=>item.trim()).filter(Boolean)}
function titleKey(row,individual=false){return [norm(row.event),norm(row.type),norm(row.team),individual?norm(row.player):''].join('|')}
function uniqueTitles(rows,individual=false){const seen=new Set();return rows.filter(row=>{const key=titleKey(row,individual);if(!key||seen.has(key))return false;seen.add(key);return true})}
function parseCollective(text){return tsvRows(text).slice(1).map(row=>({event:row[0]?.trim(),type:row[1]?.trim(),team:row[2]?.trim(),players:splitPeople(row[3])})).filter(row=>row.event&&row.team)}
function parseIndividual(text){return tsvRows(text).slice(1).map(row=>({event:row[0]?.trim(),type:row[1]?.trim(),team:row[2]?.trim(),player:row[3]?.trim()})).filter(row=>row.event&&row.team&&row.player)}
function teamMatches(team,value){const wanted=norm(value),names=[team.name,...(team.aliases||[])].map(norm);return names.includes(wanted)}
async function fetchText(url){const response=await fetch(url,{cache:'default'});if(!response.ok)throw new Error('Fonte indisponível');return response.text()}
function updateTitleSections(team,collective,individual){
  const collectiveCount=document.getElementById('historical-collective-count'),individualCount=document.getElementById('historical-individual-count'),collectiveList=document.getElementById('historical-collective-list'),individualList=document.getElementById('historical-individual-list');
  if(collectiveCount)collectiveCount.textContent=String(collective.length);
  if(individualCount)individualCount.textContent=String(individual.length);
  if(collectiveList)collectiveList.innerHTML=collective.length?collective.map(row=>titleRow(row,false,team.name)).join(''):'<div class="historical-empty">Nenhum título coletivo registrado.</div>';
  if(individualList)individualList.innerHTML=individual.length?individual.map(row=>titleRow(row,true,team.name)).join(''):'<div class="historical-empty">Nenhum prêmio individual registrado.</div>';
}
function scheduleRemoteTitles(team,localCollective,localIndividual){
  const marker=document.getElementById('historical-collective-list'),cfg=window.CFF_CONFIG?.sheets;
  if(!marker||!cfg)return;
  let started=false;
  const start=async()=>{if(started)return;started=true;const results=await Promise.allSettled([fetchText(cfg.recordesColetivos),fetchText(cfg.recordesIndividuais)]);let collective=[...localCollective],individual=[...localIndividual];if(results[0].status==='fulfilled')collective.push(...parseCollective(results[0].value).filter(row=>teamMatches(team,row.team)));if(results[1].status==='fulfilled')individual.push(...parseIndividual(results[1].value).filter(row=>teamMatches(team,row.team)));updateTitleSections(team,uniqueTitles(collective),uniqueTitles(individual,true))};
  if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>{if(entries.some(entry=>entry.isIntersecting)){observer.disconnect();start()}},{rootMargin:'500px 0px'});observer.observe(marker)}else setTimeout(start,900);
}

function playerHref(player,team=''){
  if(!player?.hasProfile)return'';
  return player.id?`jogador.html?id=${encodeURIComponent(player.id)}`:`jogador.html?jogador=${encodeURIComponent(player.name||'')}&time=${encodeURIComponent(team)}`;
}
function playerCard(player,team,notable=false){
  const href=playerHref(player,team);
  const tag=href?'a':'div';
  const stats=player.kills?`${fmt(player.kills)} K • ${fmt(player.matches)} Q • ${Number(player.avg||0).toFixed(2)} K/Q`:(player.cargo||'Jogador');
  return`<${tag} class="historical-player-card"${href?` href="${href}"`:''}><img src="${esc(player.photo||'silhueta.webp')}" loading="lazy" decoding="async" onerror="this.onerror=null;this.src='silhueta.webp'" alt="${esc(player.name)}"><span><strong>${esc(player.name||'Jogador')}</strong><small>${esc(notable?stats:(player.cargo||stats))}</small></span></${tag}>`;
}
function personRow(player,team){
  const href=playerHref(player,team),tag=href?'a':'div';
  const sub=[player.cargo||'Jogador',player.kills?`${fmt(player.kills)} K`:null].filter(Boolean).join(' • ');
  return`<${tag} class="historical-person-row"${href?` href="${href}"`:''}><img src="${esc(player.photo||'silhueta.webp')}" loading="lazy" decoding="async" onerror="this.onerror=null;this.src='silhueta.webp'" alt="${esc(player.name)}"><span><strong>${esc(player.name||'Jogador')}</strong><small>${esc(sub)}</small></span></${tag}>`;
}
function participationRow(row){
  const position=Number(row.position)>0?`${Number(row.position)}º`:row.status||'Participou';
  return`<div class="historical-participation-row"><div><strong>${esc(row.event||'Competição')}</strong><small>${esc(row.year||'')}${row.status&&row.status!==position?` • ${esc(row.status)}`:''}</small></div><div class="historical-position">${esc(position)}</div></div>`;
}
function titleRow(row,individual=false,team=''){
  const content=`<div><strong>${esc(row.event||'Título')}</strong><small>${esc(row.type||'Premiação')}${row.player?` • ${esc(row.player)}`:''}</small></div><span>🏆</span>`;
  if(individual&&row.player)return`<a class="historical-title-row" href="jogador.html?jogador=${encodeURIComponent(row.player)}&time=${encodeURIComponent(team)}">${content}</a>`;
  return`<div class="historical-title-row">${content}</div>`;
}
function directoryCard(team){
  const last=team.lastParticipation;
  const sub=last?`Última participação: ${last.event}${last.year?` • ${last.year}`:''}`:`${team.players.length} jogador${team.players.length===1?'':'es'} registrado${team.players.length===1?'':'s'}`;
  return`<a class="historical-directory-card" href="equipe-historica.html?time=${encodeURIComponent(team.name)}"><img src="${esc(safeLogo(team))}" loading="lazy" decoding="async" onerror="this.onerror=null;this.src='escudo.webp'" alt="${esc(team.name)}"><span><strong>${esc(team.name)}</strong><small>${esc(sub)}</small></span></a>`;
}
async function renderDirectory(){
  try{
    const data=await loadData();
    const teams=(data.teams||[]).filter(team=>!team.isCurrentS2);
    directory.innerHTML=`<section class="historical-directory-head"><div><h1>Equipes históricas</h1><p>Organizações com passagens registradas no cenário competitivo.</p></div><input class="historical-directory-search" id="historical-team-search" type="search" placeholder="Pesquisar equipe..." autocomplete="off"></section><p class="historical-directory-count" id="historical-team-count"></p><div class="historical-directory-grid" id="historical-team-grid"></div>`;
    const input=document.getElementById('historical-team-search'),grid=document.getElementById('historical-team-grid'),count=document.getElementById('historical-team-count');
    const paint=()=>{
      const query=norm(input.value);
      const filtered=teams.filter(team=>!query||norm([team.name,...(team.aliases||[])].join(' ')).includes(query));
      count.textContent=`${filtered.length} equipe${filtered.length===1?'':'s'}`;
      grid.innerHTML=filtered.length?filtered.map(directoryCard).join(''):'<div class="historical-no-results">Nenhuma equipe encontrada.</div>';
    };
    input.addEventListener('input',paint);
    paint();
  }catch(error){directory.innerHTML=`<div class="historical-team-error"><strong>${esc(error.message)}</strong><a href="index.html">Voltar para a página inicial</a></div>`}
}
function findTeam(teams,value){
  const wanted=norm(value);
  return teams.find(team=>norm(team.name)===wanted||norm(team.slug)===wanted||(team.aliases||[]).some(alias=>norm(alias)===wanted));
}
async function renderProfile(){
  try{
    const data=await loadData();
    const params=new URLSearchParams(location.search);
    const wanted=params.get('time')||params.get('team')||params.get('id')||'';
    const team=findTeam(data.teams||[],wanted);
    if(!team)throw new Error('Equipe não encontrada.');
    document.title=`${team.name} | Central Free Fire`;
    const last=team.lastParticipation;
    const lastText=last?`${last.event}${last.position?` • ${last.position}º`:last.status?` • ${last.status}`:''}`:'Sem participação cadastrada';
    const currentLink=team.isCurrentS2?`<a class="historical-team-current-link" href="equipe.html?time=${encodeURIComponent(team.name)}">Ver perfil da WB 2026 S2</a>`:'';
    const notable=team.notablePlayers||[],participations=team.participations||[],collective=team.collectiveTitles||[],individual=team.individualTitles||[],players=team.players||[],staff=team.staff||[];
    profile.innerHTML=`
      <section class="historical-team-hero"><div class="historical-team-logo-wrap"><img class="historical-team-logo" src="${esc(safeLogo(team))}" decoding="async" onerror="this.onerror=null;this.src='escudo.webp'" alt="${esc(team.name)}"></div><div><div class="historical-team-kicker">Histórico da organização</div><h1 class="historical-team-name">${esc(team.name)}</h1><div class="historical-team-last">Última participação registrada: <strong>${esc(lastText)}</strong></div>${currentLink}</div></section>
      <section class="historical-summary-grid"><div class="historical-summary-card"><small>Títulos coletivos</small><strong id="historical-collective-count">${collective.length}</strong></div><div class="historical-summary-card"><small>Prêmios individuais</small><strong id="historical-individual-count">${individual.length}</strong></div><div class="historical-summary-card"><small>Jogadores registrados</small><strong>${players.length}</strong></div><div class="historical-summary-card"><small>Participações</small><strong>${participations.length}</strong></div></section>
      <section class="historical-section"><div class="historical-section-head"><h2>Jogadores notáveis</h2><p>Destaques com maior histórico estatístico registrado</p></div>${notable.length?`<div class="historical-player-grid">${notable.map(player=>playerCard(player,team.name,true)).join('')}</div>`:'<div class="historical-empty">Ainda não há estatísticas suficientes para destacar jogadores.</div>'}</section>
      <section class="historical-section"><div class="historical-section-head"><h2>Participações recentes</h2><p>Últimas edições cadastradas</p></div>${participations.length?`<div class="historical-participation-list">${participations.map(participationRow).join('')}</div>`:'<div class="historical-empty">Nenhuma participação registrada.</div>'}</section>
      <section class="historical-section"><div class="historical-section-head"><h2>Títulos coletivos</h2><p>Conquistas registradas pela organização</p></div><div class="historical-title-list" id="historical-collective-list">${collective.length?collective.map(row=>titleRow(row,false,team.name)).join(''):'<div class="historical-empty">Nenhum título coletivo registrado.</div>'}</div></section>
      <section class="historical-section"><div class="historical-section-head"><h2>Títulos e prêmios individuais</h2><p>Premiações conquistadas defendendo a equipe</p></div><div class="historical-title-list" id="historical-individual-list">${individual.length?individual.map(row=>titleRow(row,true,team.name)).join(''):'<div class="historical-empty">Nenhum prêmio individual registrado.</div>'}</div></section>
      <details class="historical-details"><summary>Jogadores que passaram pela equipe <span>${players.length}</span></summary><div class="historical-all-players">${players.map(player=>personRow(player,team.name)).join('')||'<div class="historical-empty">Nenhum jogador registrado.</div>'}</div></details>
      ${staff.length?`<details class="historical-details"><summary>Comissão técnica registrada <span>${staff.length}</span></summary><div class="historical-all-players">${staff.map(player=>personRow(player,team.name)).join('')}</div></details>`:''}`;scheduleRemoteTitles(team,collective,individual);
  }catch(error){profile.innerHTML=`<div class="historical-team-error"><strong>${esc(error.message)}</strong><a href="equipes-historicas.html">Ver equipes históricas</a></div>`}
}
if(directory)renderDirectory();
if(profile)renderProfile();
})();
